// lookup demo — Puzzle: Three boxes labeled Apples, Oranges, Mixed — all mislabeled. One fruit drawn from one box identifies all. Which box? (jahdb demo program)
var DATA={"Puzzle: Three boxes labeled Apples, Oranges, Mixed \u2014 all mislabeled. One fruit drawn from one box identifies all. Which box?":"Signature puzzle #1"};
function lookup(q){q=String(q).toLowerCase();var h=[];for(var k in DATA){if((k+" "+DATA[k]).toLowerCase().indexOf(q)>=0)h.push(k+": "+DATA[k]);}return h.length?h.join("\n"):"no match for "+q;}
function listAll(){return Object.keys(DATA).join(", ");}
console.log("sample lookup:");console.log(lookup("Draw from the Mixed-labeled box; its true contents reveal the rest by elimination."));

